# --- Data: schedules for loans booked before servicing existed ------------------------------
# A frozen copy of the Phase 10 schedule rules, so this migration never changes meaning.


def _add_months(start: date, months: int) -> date:
    years, month = divmod(start.month - 1 + months, 12)
    return date(start.year + years, month + 1, min(start.day, 28))


def _interest(balance: int, rate_bps: int) -> int:
    exact = Decimal(balance) * Decimal(rate_bps) / Decimal(120_000)
    return int(exact.quantize(Decimal(1), rounding=ROUND_HALF_UP))


def _backfill_schedules() -> None:
    bind = op.get_bind()
    loans = bind.execute(
        sa.text(
            "SELECT id, loan_number, currency, principal, annual_rate_bps, term_months, "
            "monthly_payment, disbursed_at FROM loans"
        )
    ).all()
    for loan in loans:
        receivable = bind.execute(
            sa.text(
                "INSERT INTO ledger_accounts (id, code, name, account_type, currency) "
                "VALUES (gen_random_uuid(), :code, :name, 'asset', :currency) "
                "ON CONFLICT (code) DO UPDATE SET code = EXCLUDED.code RETURNING id"
            ),
            {
                "code": f"1310-{loan.loan_number}",
                "name": f"Interest receivable {loan.loan_number}",
                "currency": loan.currency,
            },
        ).scalar_one()
        bind.execute(
            sa.text("UPDATE loans SET interest_receivable_account_id = :r WHERE id = :id"),
            {"r": receivable, "id": loan.id},
        )
        first_due = _add_months(loan.disbursed_at.date(), 1)
        balance = loan.principal
        for number in range(1, loan.term_months + 1):
            interest = _interest(balance, loan.annual_rate_bps)
            part = (
                balance
                if number == loan.term_months
                else max(0, min(balance, loan.monthly_payment - interest))
            )
            balance -= part
            bind.execute(
                sa.text(
                    "INSERT INTO loan_instalments "
                    "(id, loan_id, number, due_date, principal, interest, status) VALUES "
                    "(gen_random_uuid(), :loan, :number, :due, :principal, :interest, "
                    "'scheduled')"
                ),
                {
                    "loan": loan.id,
                    "number": number,
                    "due": _add_months(first_due, number - 1),
                    "principal": part,
                    "interest": interest,
                },
            )
